#!/usr/bin/env python3

"""
Reproduction script for the annotated types serialization strategy issue.
"""

from dataclasses import dataclass
from typing import Annotated, TypeAlias
from mashumaro import DataClassDictMixin

# Define annotated types as described in the issue
PositiveInt: TypeAlias = Annotated[int, "PositiveInt"]
NegativeInt: TypeAlias = Annotated[int, "NegativeInt"]

def deserialize_positive_int(value):
    print(f"Deserializing positive int: {value}")
    if value < 0:
        raise ValueError("value < 0")
    return value

def deserialize_negative_int(value):
    print(f"Deserializing negative int: {value}")
    if value >= 0:
        raise ValueError("value >= 0")
    return value

@dataclass
class MyClass(DataClassDictMixin):
    positive_int: PositiveInt
    negative_int: NegativeInt

    class Config:
        serialization_strategy = {
            PositiveInt: {
                "deserialize": deserialize_positive_int,
            },
            NegativeInt: {
                "deserialize": deserialize_negative_int,
            }
        }

def test_annotated_serialization_strategies():
    """Test that annotated types can have different serialization strategies."""
    print("Testing annotated serialization strategies...")

    # This should work - PositiveInt should use deserialize_positive_int
    # and NegativeInt should use deserialize_negative_int
    try:
        # Test valid case
        obj = MyClass.from_dict({"positive_int": 5, "negative_int": -3})
        print(f"Success: {obj}")

        # Test invalid positive int
        try:
            obj = MyClass.from_dict({"positive_int": -5, "negative_int": -3})
            print("ERROR: Should have failed for negative positive_int")
        except ValueError as e:
            print(f"Correctly caught error for negative positive_int: {e}")

        # Test invalid negative int  
        try:
            obj = MyClass.from_dict({"positive_int": 5, "negative_int": 3})
            print("ERROR: Should have failed for positive negative_int")
        except ValueError as e:
            print(f"Correctly caught error for positive negative_int: {e}")

    except Exception as e:
        print(f"Failed with exception: {e}")
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
    test_annotated_serialization_strategies()

