#!/usr/bin/env python3

"""
Detailed reproduction script to understand how annotated types work in mashumaro.
"""

from dataclasses import dataclass
from typing import Annotated
from typing_extensions import TypeAlias
from mashumaro import DataClassDictMixin

# Define annotated types as described in the issue
PositiveInt: TypeAlias = Annotated[int, "PositiveInt"]
NegativeInt: TypeAlias = Annotated[int, "NegativeInt"]

call_log = []

def deserialize_positive_int(value):
    call_log.append(("positive_int", value))
    print(f"[POSITIVE_INT] Deserializing: {value}")
    if value < 0:
        raise ValueError("value < 0")
    return value

def deserialize_negative_int(value):
    call_log.append(("negative_int", value))
    print(f"[NEGATIVE_INT] Deserializing: {value}")
    if value >= 0:
        raise ValueError("value >= 0")
    return value

# Also test with regular int to see if it interferes
def deserialize_regular_int(value):
    call_log.append(("regular_int", value))
    print(f"[REGULAR_INT] Deserializing: {value}")
    return value

@dataclass
class MyClassWithAnnotated(DataClassDictMixin):
    positive_int: PositiveInt
    negative_int: NegativeInt

    class Config:
        serialization_strategy = {
            PositiveInt: {
                "deserialize": deserialize_positive_int,
            },
            NegativeInt: {
                "deserialize": deserialize_negative_int,
            }
        }

@dataclass  
class MyClassWithoutAnnotated(DataClassDictMixin):
    regular_int: int

    class Config:
        serialization_strategy = {
            int: {
                "deserialize": deserialize_regular_int,
            }
        }

@dataclass
class MixedClass(DataClassDictMixin):
    positive_int: PositiveInt
    regular_int: int

    class Config:
        serialization_strategy = {
            PositiveInt: {
                "deserialize": deserialize_positive_int,
            },
            int: {
                "deserialize": deserialize_regular_int,
            }
        }

def test_pure_annotated():
    """Test that annotated types work independently.""" 
    print("=== Testing pure annotated types ===")
    global call_log
    call_log = []

    obj = MyClassWithAnnotated.from_dict({"positive_int": 5, "negative_int": -3})
    print(f"Result: {obj}")
    print(f"Call log: {call_log}")

    # Check that both specific handlers were called
    assert ("positive_int", 5) in call_log
    assert ("negative_int", -3) in call_log
    assert len(call_log) == 2
    print("✓ Pure annotated test passed")

def test_regular_int():
    """Test that regular int works.""" 
    print("\n=== Testing regular int ===")
    global call_log
    call_log = []

    obj = MyClassWithoutAnnotated.from_dict({"regular_int": 42})
    print(f"Result: {obj}")
    print(f"Call log: {call_log}")

    assert ("regular_int", 42) in call_log
    assert len(call_log) == 1
    print("✓ Regular int test passed")

def test_mixed():
    """Test mixed annotated and regular types."""
    print("\n=== Testing mixed annotated and regular ===")
    global call_log
    call_log = []

    obj = MixedClass.from_dict({"positive_int": 7, "regular_int": 42})
    print(f"Result: {obj}")
    print(f"Call log: {call_log}")

    # Check that the right handlers were called for each type
    assert ("positive_int", 7) in call_log  # Annotated handler
    assert ("regular_int", 42) in call_log  # Regular handler
    assert len(call_log) == 2
    print("✓ Mixed test passed")

def test_fallback_behavior():
    """Test what happens when no strategy is defined for annotated type."""
    print("\n=== Testing fallback behavior ===")

    @dataclass
    class NoStrategyClass(DataClassDictMixin):
        positive_int: PositiveInt
        # No specific strategy for PositiveInt

    try:
        obj = NoStrategyClass.from_dict({"positive_int": 5})
        print(f"Result: {obj}")
        print("✓ Fallback worked (uses default int behavior)")
    except Exception as e:
        print(f"✗ Fallback failed: {e}")

if __name__ == "__main__":
    test_pure_annotated()
    test_regular_int() 
    test_mixed()
    test_fallback_behavior()
    print("\n=== All tests completed ===")

